/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let result = match self.state {
            State::ExpectingItem => {
                self.skip_blanks();
                if self.at_end() {
                    return None;
                }
                self.scan_item()
            }
            State::ExpectingValue => self.scan_value(),
            State::Failed => return None,
        };
        if result.is_err() {
            self.state = State::Failed;
            self.pos = self.src.len();
        }
        Some(result)
    }
}

type Scan<'a> = Result<Token<'a>, LexError>;

#[inline(always)]
fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

impl<'a> Tokens<'a> {
    #[inline(always)]
    fn bytes(&self) -> &'a [u8] {
        self.src.as_bytes()
    }

    #[inline(always)]
    fn at_end(&self) -> bool {
        self.pos >= self.src.len()
    }

    #[inline(always)]
    fn skip_blanks(&mut self) {
        let bytes = self.bytes();
        while self.pos < bytes.len() && is_blank(bytes[self.pos]) {
            self.pos += 1;
        }
    }

    #[inline(always)]
    fn scan_item(&mut self) -> Scan<'a> {
        match self.bytes()[self.pos] {
            b'[' => self.scan_timestamp(),
            b'"' => Err(LexError::UnexpectedQuote { pos: self.pos }),
            b'=' => Err(LexError::EmptyKey { pos: self.pos }),
            _ => self.scan_key_or_word(),
        }
    }

    /// `[` text `]`, followed by a blank or the end of the line.
    #[inline(always)]
    fn scan_timestamp(&mut self) -> Scan<'a> {
        let bytes = self.bytes();
        let start = self.pos + 1;
        let mut end = start;
        loop {
            match bytes.get(end) {
                None => return Err(LexError::UnterminatedTimestamp { pos: self.pos }),
                Some(b']') => break,
                Some(b'[') => return Err(LexError::NestedBracket { pos: end }),
                Some(_) => end += 1,
            }
