#[path = "../src/token.rs"]
mod newtok;
mod error { pub use logscan::LexError; }
#[path = "../tests/support/reference.rs"]
mod reference;
use std::time::{Duration, Instant};

fn run_old(text: &str) -> (Duration, usize) {
    let t = Instant::now();
    let mut n = 0usize;
    for l in text.lines() { for t in reference::ref_tokenize(l) { n += t.is_ok() as usize; } }
    (t.elapsed(), n)
}
fn run_new(text: &str) -> (Duration, usize) {
    let t = Instant::now();
    let mut n = 0usize;
    for l in text.lines() { for t in newtok::tokenize(l) { n += t.is_ok() as usize; } }
    (t.elapsed(), n)
}
fn main() {
    let lines = [
        r#"[2024-05-01T12:00:00Z] level=info msg="disk 91% full, \"retrying\"" user=ann host=web-01 latency=123 ok"#,
        "started worker-3 ok a=1 b= c=xyz",
    ];
    let text: String = (0..200_000).map(|i| format!("{}\n", lines[i % 2])).collect();
    let (mut mo, mut mn) = (Duration::MAX, Duration::MAX);
    for round in 0..100 {
        let ((o, a), (n, b)) = if round % 2 == 0 { let o = run_old(&text); (o, run_new(&text)) } else { let n = run_new(&text); (run_old(&text), n) };
        assert_eq!(a, b);
        mo = mo.min(o.0); mn = mn.min(n.0);
    }
    println!("min old {mo:?} new {mn:?} ratio {:.3}", mn.as_secs_f64() / mo.as_secs_f64());
